// StatusContainsFold applies the ContainsFold predicate on the "status" field.
func StatusContainsFold(v string) predicate.Conversation {
	return predicate.Conversation(sql.FieldContainsFold(FieldStatus, v))
}

// HasCreatorAgent applies the HasEdge predicate on the "creator_agent" edge.
func HasCreatorAgent() predicate.Conversation {
	return predicate.Conversation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CreatorAgentTable, CreatorAgentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCreatorAgentWith applies the HasEdge predicate on the "creator_agent" edge with a given conditions (other predicates).
func HasCreatorAgentWith(preds ...predicate.Agent) predicate.Conversation {
	return predicate.Conversation(func(s *sql.Selector) {
		step := newCreatorAgentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

